css:
.loader { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size) * .05); width: var(--loader-size); height: calc(var(--loader-size) * .4); }
.loader span { width: calc(var(--loader-size) * .16); height: calc(var(--loader-size) * .16); border-top: calc(var(--loader-size) * .05) solid var(--loader-color); border-right: calc(var(--loader-size) * .05) solid var(--loader-color); animation: twMarch calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .15); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .3); }
@keyframes twMarch { 0%, 100% { opacity: .25; transform: rotate(45deg) translate(0, 0); } 50% { opacity: 1; transform: rotate(45deg) translate(14%, -14%); } }
